const LinterMessage = require('./message')
const { Allowlist, isBuiltIn } = require('./config')

// Checks uploaded CSV data files against the entity 'extension-allowlist'.
// Only entities that are allowed to be extended may also receive data via CSV.

// Maps a CSV data file name to the fully-qualified entity name it provides data for.
// Mirrors the convention in cds core (cds/lib/dbs/cds-deploy.js _entity4)
const entityNameFromCsvFile = (file, csn) => {
  const base = file.replace(/\.csv$/i, '')
  const name = base.replace(/-/g, '.')
  if (csn?.definitions?.[name]) return name
  // localization files: 'Books.texts', 'Books.texts_de', 'Books_texts'
  const m = /(.+)[._]texts_?/.exec(name)
  if (m) {
    const target = csn?.definitions?.[m[1]]?.elements?.texts?.target
    if (target) return target
  }
  return null
}

module.exports = class CsvAllowlistChecker {

  check(csvNames, fullCsn, mtxConfig) {
    // no restriction if no allowlist is configured or no data is uploaded
    if (!Object.keys(mtxConfig ?? {}).length) return []
    if (!csvNames || !csvNames.length) return []

    const allowList = new Allowlist(mtxConfig, fullCsn)
    const messages = []

    for (const csvName of csvNames) {
      // ignore hidden/metadata files (e.g. macOS AppleDouble '._*' created by tar);
      // these are never valid entity data files
      if (!csvName || csvName.startsWith('.')) continue

      const name = entityNameFromCsvFile(csvName, fullCsn)

      // unknown entity (not resolvable in the model) -> cannot be on the allowlist -> block
      if (!name) {
        messages.push(this._createWarning(csvName, allowList.getList('entity')))
        continue
      }

      // built-in namespaces stay allowed, consistent with model extension checks
      if (isBuiltIn(name)) continue

      const kind = fullCsn?.definitions?.[name]?.kind ?? 'entity'
      if (!allowList.isAllowed(kind, name)) {
        messages.push(this._createWarning(name, allowList.getList('entity')))
      }
    }

    return messages
  }

  _createWarning(entityName, allowlist = {}) {
    const list = Object.keys(allowlist ?? {})
    const message =
      `Data upload for entity '${entityName}' is not allowed` +
      `. Check entity allowlist: ${list.length > 0 ? list : '<empty list>'}`
    return new LinterMessage(message, { name: entityName })
  }
}
